import React,{useState} from 'react';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const lines=(value,length=22)=>{const chars=Array.from(String(value||'')),result=[];for(let i=0;i<chars.length;i+=length)result.push(chars.slice(i,i+length).join(''));return result;};
function svgContent(nodes,edges,points){
 const cards=nodes.filter(n=>points[n.id]),ids=new Set(cards.map(n=>n.id));if(!cards.length)throw new Error('画布没有可导出的内容');
 const x=Math.min(...cards.map(n=>points[n.id].x))-40,y=Math.min(...cards.map(n=>points[n.id].y))-40,w=Math.max(...cards.map(n=>points[n.id].x+280))-x+40,h=Math.max(...cards.map(n=>points[n.id].y+172))-y+40;
 const links=edges.filter(e=>ids.has(e.from)&&ids.has(e.to)).map(e=>{const a=points[e.from],b=points[e.to],sx=a.x+280,sy=a.y+50,tx=b.x,ty=b.y+50;return '<path d="M'+sx+' '+sy+' C'+(sx+80)+' '+sy+','+(tx-80)+' '+ty+','+tx+' '+ty+'" fill="none" stroke="#7898b8" stroke-width="2"/><text x="'+((sx+tx)/2)+'" y="'+((sy+ty)/2-8)+'" text-anchor="middle" font-size="12" fill="#46627e">'+esc(e.name||e.label||'')+'</text>';}).join('');
 const boxes=cards.map(n=>{const at=points[n.id];return '<g transform="translate('+at.x+' '+at.y+')"><rect width="280" height="172" rx="14" fill="#f5f8fd" stroke="#9ab3d4"/><text x="18" y="30" fill="#203d5c" font-size="17" font-weight="600">'+esc(lines(n.title||n.name,15)[0])+'</text>'+lines(n.summary||'',22).slice(0,5).map((l,i)=>'<text x="18" y="'+(56+i*21)+'" font-size="13" fill="#536b84">'+esc(l)+'</text>').join('')+'</g>';}).join('');
 return {w,h,svg:'<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="'+x+' '+y+' '+w+' '+h+'"><rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="#ffffff"/><g font-family="Microsoft YaHei, PingFang SC, sans-serif">'+links+boxes+'</g></svg>'};
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function CanvasExport({nodes,edges,points,name='画布'}){const [busy,setBusy]=useState(false),[error,setError]=useState('');const save=async format=>{setBusy(true);setError('');try{const {svg,w,h}=svgContent(nodes,edges,points),blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),filename=String(name).replace(/[\\/:*?"<>|]/g,'_');if(format==='svg'){download(blob,filename+'.svg');return;}const url=URL.createObjectURL(blob);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('图片导出失败，请使用 SVG'));image.src=url;});const scale=Math.min(2,8192/w,8192/h,Math.sqrt(24000000/(w*h))),canvas=document.createElement('canvas');canvas.width=Math.ceil(w*scale);canvas.height=Math.ceil(h*scale);const ctx=canvas.getContext('2d');if(!ctx)throw new Error('无法创建图片画布');ctx.drawImage(image,0,0,canvas.width,canvas.height);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw new Error('图片过大，请使用 SVG');download(png,filename+'.png');}finally{URL.revokeObjectURL(url);}}catch(e){setError(e.message);}finally{setBusy(false);}};return <div className="canvas-export"><button disabled={busy} onClick={()=>save('svg')}>导出 SVG</button><button disabled={busy} onClick={()=>save('png')}>导出 PNG</button>{error&&<small role="alert">{error}</small>}<style>{'.cuigengji .canvas-export{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-left:auto}.cuigengji .canvas-export button{padding:5px 9px;font-size:12px}.cuigengji .canvas-export small{color:var(--cg-danger,#b24b4b)}'}</style></div>;}
